ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS task_response_hours integer NOT NULL DEFAULT 24, ADD COLUMN IF NOT EXISTS installment_alert_days integer NOT NULL DEFAULT 3, ADD COLUMN IF NOT EXISTS contract_alert_months integer NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS contract_second_alert_days integer NOT NULL DEFAULT 7, ADD COLUMN IF NOT EXISTS task_summary_time time NOT NULL DEFAULT '00:00', ADD COLUMN IF NOT EXISTS task_timezone text NOT NULL DEFAULT 'Asia/Riyadh', ADD COLUMN IF NOT EXISTS task_telegram_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS public.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,type text NOT NULL,assignee_user_id uuid,due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','done','cancelled')),entity_type text NOT NULL CHECK(entity_type IN('unit','party','opportunity','booking','contract','installment')),entity_id uuid NOT NULL,created_by uuid,completed_at timestamptz,outcome_note text,source_key text UNIQUE,visibility text NOT NULL DEFAULT 'operational' CHECK(visibility IN('operational','financial','escalation')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tasks TO authenticated;GRANT ALL ON public.tasks TO service_role;ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE INDEX IF NOT EXISTS tasks_inbox ON public.tasks(assignee_user_id,status,due_at,id);
CREATE TABLE IF NOT EXISTS public.user_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,task_id uuid REFERENCES public.tasks(id),title text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,task_id));GRANT SELECT ON public.user_notifications TO authenticated;GRANT ALL ON public.user_notifications TO service_role;ALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.task_generation_state(source_key text PRIMARY KEY,task_id uuid REFERENCES public.tasks(id),last_checked_at timestamptz NOT NULL DEFAULT now());GRANT ALL ON public.task_generation_state TO service_role;ALTER TABLE public.task_generation_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.notification_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,task_id uuid REFERENCES public.tasks(id),kind text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','claimed','accepted','failed','uncertain','cancelled')),source_key text NOT NULL UNIQUE,claimed_at timestamptz,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),result_code text);GRANT ALL ON public.notification_outbox TO service_role;ALTER TABLE public.notification_outbox ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.party_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),party_id uuid NOT NULL REFERENCES public.parties(id),activity_type public.opportunity_activity_type NOT NULL,outcome public.opportunity_activity_outcome NOT NULL,notes text,next_action text,next_action_at timestamptz,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.party_activities TO authenticated;GRANT ALL ON public.party_activities TO service_role;ALTER TABLE public.party_activities ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.team_saved_views(code text PRIMARY KEY,name_ar text NOT NULL,required_capability text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.team_saved_views TO authenticated;GRANT ALL ON public.team_saved_views TO service_role;ALTER TABLE public.team_saved_views ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.task_staff_active(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.staff_accounts s WHERE s.user_id=_user AND s.status='inactive') AND EXISTS(SELECT 1 FROM public.user_role_assignments a JOIN public.roles r ON r.code=a.role AND r.is_active WHERE a.user_id=_user AND a.is_active) $$;
CREATE OR REPLACE FUNCTION public.task_can_read(_task public.tasks) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.task_staff_active(auth.uid()) AND NOT public.has_role(auth.uid(),'investor') AND NOT public.has_role(auth.uid(),'tenant') AND NOT public.has_role(auth.uid(),'user') AND (public.has_permission('tasks.manage','view') OR (_task.assignee_user_id=auth.uid() AND public.has_permission('tasks.own','own'))) AND CASE _task.visibility WHEN 'financial' THEN public.finance_can_read() WHEN 'escalation' THEN public.has_role(auth.uid(),'leasing_manager') OR public.has_role(auth.uid(),'admin') ELSE true END AND NOT(public.has_role(auth.uid(),'sales_agent') AND _task.visibility<>'operational') AND CASE WHEN public.has_role(auth.uid(),'sales_agent') AND _task.entity_type='opportunity' THEN EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=_task.entity_id AND o.owner_user_id=auth.uid()) WHEN public.has_role(auth.uid(),'sales_agent') AND _task.entity_type='party' THEN EXISTS(SELECT 1 FROM public.opportunities o WHERE o.party_id=_task.entity_id AND o.owner_user_id=auth.uid() AND o.outcome IS NULL) WHEN public.has_role(auth.uid(),'sales_agent') AND _task.entity_type='booking' THEN EXISTS(SELECT 1 FROM public.opportunities o WHERE o.booking_id=_task.entity_id AND o.owner_user_id=auth.uid()) ELSE true END $$;
CREATE POLICY tasks_read ON public.tasks FOR SELECT TO authenticated USING(public.task_can_read(tasks));
CREATE POLICY notification_own ON public.user_notifications FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.task_staff_active(auth.uid()) AND (task_id IS NULL OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=task_id)));
CREATE POLICY party_activity_read ON public.party_activities FOR SELECT TO authenticated USING(public.can_read_party_contact(party_id));
CREATE POLICY team_views_read ON public.team_saved_views FOR SELECT TO authenticated USING(public.has_permission(required_capability,'view') OR public.has_permission(required_capability,'own'));
CREATE OR REPLACE FUNCTION public.tasks_bootstrap(_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_permission('security.roles','edit') THEN RAISE EXCEPTION 'إعداد المهام للأدمن فقط';END IF;PERFORM public._assert_reason(_reason);INSERT INTO public.capabilities(code,name_ar,category) VALUES('tasks.own','مهامي','المتابعة'),('tasks.manage','إدارة مهام الفريق','المتابعة') ON CONFLICT DO NOTHING;INSERT INTO public.role_permissions(role,capability,level,updated_by) SELECT r.code,c.code,CASE WHEN c.code='tasks.manage' AND r.code='admin' THEN 'edit' WHEN c.code='tasks.manage' AND r.code IN('manager','leasing_manager') THEN 'view' WHEN c.code='tasks.own' AND r.code IN('admin','leasing_manager','sales_agent','accountant','control') THEN 'own' ELSE 'none' END,auth.uid() FROM public.roles r CROSS JOIN public.capabilities c WHERE c.code IN('tasks.own','tasks.manage') ON CONFLICT DO NOTHING;INSERT INTO public.team_saved_views(code,name_ar,required_capability) VALUES('no_followup','عملائي بدون متابعة','opportunities.read'),('holds_today','حجوزات تنتهي اليوم','bookings.hold'),('overdue','أقساط متأخرة','finance.read'),('renewals','عقود قاربت الانتهاء','contracts.draft'),('untouched_targets','مستهدفون بلا تواصل','opportunities.read') ON CONFLICT DO NOTHING;PERFORM public._safety_audit('TASKS_BOOTSTRAP','tasks','settings',NULL,jsonb_build_object('response_hours',24,'installment_days',3,'contract_months',1,'contract_second_days',7),'إعداد المهام: '||_reason);END $$;
CREATE OR REPLACE FUNCTION public.tasks_page(_status text DEFAULT 'open',_search text DEFAULT '',_offset integer DEFAULT 0,_limit integer DEFAULT 25,_today boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'سجل الدخول';END IF;WITH f AS(SELECT t.* FROM public.tasks t WHERE public.task_can_read(t) AND (_status='all' OR t.status=_status) AND (_search='' OR t.title ILIKE '%'||_search||'%') AND (NOT _today OR (t.assignee_user_id=auth.uid() AND t.due_at<((now() AT TIME ZONE 'Asia/Riyadh')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh'))),p AS(SELECT * FROM f ORDER BY due_at,id LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM p),'[]'),'count',(SELECT count(*) FROM f),'as_of',now()) INTO result;RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.set_task_state(_id uuid,_status text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tasks;BEGIN PERFORM public._assert_reason(_note);IF _status NOT IN('done','cancelled') THEN RAISE EXCEPTION 'اختر منجزة أو ملغاة';END IF;SELECT * INTO t FROM public.tasks WHERE id=_id FOR UPDATE;IF NOT FOUND OR NOT public.task_can_read(t) OR NOT(public.has_permission('tasks.manage','edit') OR (t.assignee_user_id=auth.uid() AND public.has_permission('tasks.own','own') AND NOT public.has_role(auth.uid(),'manager'))) THEN RAISE EXCEPTION 'غير مسموح بتعديل المهمة';END IF;IF t.status<>'open' THEN RAISE EXCEPTION 'المهمة مغلقة بالفعل';END IF;UPDATE public.tasks SET status=_status,completed_at=now(),outcome_note=_note,updated_at=now() WHERE id=t.id;PERFORM public._safety_audit('TASK_STATE_CHANGED','tasks',t.id::text,to_jsonb(t),(SELECT to_jsonb(x) FROM public.tasks x WHERE id=t.id),_note);END $$;
CREATE OR REPLACE FUNCTION public.notifications_page(_offset integer DEFAULT 0,_limit integer DEFAULT 20) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH f AS(SELECT n.* FROM public.user_notifications n LEFT JOIN public.tasks t ON t.id=n.task_id WHERE n.user_id=auth.uid() AND public.task_staff_active(auth.uid()) AND (n.task_id IS NULL OR public.task_can_read(t))),p AS(SELECT * FROM f ORDER BY created_at DESC,id LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM p),'[]'),'count',(SELECT count(*) FROM f),'unread',(SELECT count(*) FROM f WHERE read_at IS NULL),'as_of',now()) $$;
CREATE OR REPLACE FUNCTION public.mark_notifications_read(_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'سجل الدخول';END IF;UPDATE public.user_notifications n SET read_at=now() WHERE n.user_id=auth.uid() AND n.read_at IS NULL AND (_id IS NULL OR n.id=_id) AND (n.task_id IS NULL OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=n.task_id AND public.task_can_read(t)));END $$;
CREATE OR REPLACE FUNCTION public.save_task_settings(_response integer,_installment integer,_months integer,_second integer,_time time,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_row jsonb;BEGIN IF NOT public.has_permission('security.roles','edit') THEN RAISE EXCEPTION 'الإعدادات للأدمن';END IF;PERFORM public._assert_reason(_reason);IF _response NOT BETWEEN 1 AND 24 OR _installment NOT BETWEEN 1 AND 365 OR _months NOT BETWEEN 1 AND 12 OR _second NOT BETWEEN 1 AND 365 OR _time IS NULL THEN RAISE EXCEPTION 'مواعيد غير صالحة؛ التواصل لا يتجاوز ٢٤ ساعة';END IF;SELECT to_jsonb(s) INTO before_row FROM public.app_settings s WHERE id=1 FOR UPDATE;UPDATE public.app_settings SET task_response_hours=_response,installment_alert_days=_installment,contract_alert_months=_months,contract_second_alert_days=_second,task_summary_time=_time,updated_at=now(),updated_by=auth.uid() WHERE id=1;PERFORM public._safety_audit('TASK_SETTINGS_CHANGED','app_settings','1',before_row,(SELECT to_jsonb(s) FROM public.app_settings s WHERE id=1),_reason);END $$;
REVOKE ALL ON FUNCTION public.task_staff_active(uuid),public.task_can_read(public.tasks),public.tasks_bootstrap(text),public.tasks_page(text,text,integer,integer,boolean),public.set_task_state(uuid,text,text),public.notifications_page(integer,integer),public.mark_notifications_read(uuid),public.save_task_settings(integer,integer,integer,integer,time,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.task_staff_active(uuid),public.task_can_read(public.tasks),public.tasks_bootstrap(text),public.tasks_page(text,text,integer,integer,boolean),public.set_task_state(uuid,text,text),public.notifications_page(integer,integer),public.mark_notifications_read(uuid),public.save_task_settings(integer,integer,integer,integer,time,text) TO authenticated,service_role;
SELECT to_regclass('public.tasks') IS NOT NULL AS tasks_ready,to_regclass('public.user_notifications') IS NOT NULL AS bell_ready;